package org.apache.commons.compress.archivers.cpio;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.HashMap;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.cpio.CpioArchiveOutputStream;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CharsetNames;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertThrows;

public class CpioArchiveOutputStream_CpioArchiveOutputStream_TriageGen1Test {

    private static final short FORMAT_NEW = CpioArchiveOutputStream.FORMAT_NEW;
    private static final short FORMAT_NEW_CRC = CpioArchiveOutputStream.FORMAT_NEW_CRC;
    private static final short FORMAT_OLD_ASCII = CpioArchiveOutputStream.FORMAT_OLD_ASCII;
    private static final short FORMAT_OLD_BINARY = CpioArchiveOutputStream.FORMAT_OLD_BINARY;
    private static final short INVALID_FORMAT = 99;

    @Test
    public void testConstructorWithValidFormats() throws IOException {
        OutputStream out = new ByteArrayOutputStream();
        int blockSize = 1024;
        String encoding = "UTF-8";

        // Test all valid formats to cover all switch branches
        new CpioArchiveOutputStream(out, FORMAT_NEW, blockSize, encoding);
        new CpioArchiveOutputStream(out, FORMAT_NEW_CRC, blockSize, encoding);
        new CpioArchiveOutputStream(out, FORMAT_OLD_ASCII, blockSize, encoding);
        new CpioArchiveOutputStream(out, FORMAT_OLD_BINARY, blockSize, encoding);
    }

    @Test
    public void testConstructorWithInvalidFormatThrowsException() {
        OutputStream out = new ByteArrayOutputStream();
        int blockSize = 1024;
        String encoding = "UTF-8";

        // Test the default branch in switch statement
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            new CpioArchiveOutputStream(out, INVALID_FORMAT, blockSize, encoding);
        });

        assert(exception.getMessage().contains("Unknown format: " + INVALID_FORMAT));
    }

    @Test
    public void testConstructorWithNullOutputStream() throws IOException {
        // Testing that the constructor accepts null (as the code doesn't explicitly check for null out)
        // but subsequent writes would fail. This ensures we cover the assignment line.
        new CpioArchiveOutputStream(null, FORMAT_NEW, 1024, "UTF-8");
    }

    @Test
    public void testConstructorWithNullEncoding() throws IOException {
        // Testing behavior when encoding is null to ensure ZipEncodingHelper is called
        OutputStream out = new ByteArrayOutputStream();
        new CpioArchiveOutputStream(out, FORMAT_NEW, 1024, null);
    }
}
